// The scene hung on a wall: a thin dark frame, a white mat, and a small museum
// label below it on the right.
export function get(app) {
  const { title, note, wallColor, frameColor, matColor } = app.state
  return (
    <div className={`flex flex-col w-full h-full p-[5vh] bg-[${wallColor}]`}>
      <div className={`flex flex-col flex-1 min-h-0 p-[1vh] bg-[${frameColor}]`}>
        <div className={`flex flex-col flex-1 min-h-0 p-[4vh] bg-[${matColor}]`}>
          <yield />
        </div>
      </div>
      <div className="flex justify-end pt-[2.5vh]">
        <div className={`flex flex-col w-[36vw] min-w-0 px-[1.4vw] py-[0.9vh] bg-[${matColor}] text-[#222222]`}>
          <span className="text-[3vh] font-bold truncate">{title || app.frame.sceneName || ''}</span>
          {note ? <span className="text-[2.2vh] truncate">{note}</span> : null}
        </div>
      </div>
    </div>
  )
}
